@njit
def check_collective_encounter(positions, target_positions, r, shared_depletion=True):
    '''
    Optimized loop-based version of check_collective_encounter_og.
    No heap allocations: no reflected lists, no set, no (Na x Nt) distance matrix.
    Uses squared distances to avoid sqrt.

    If shared_depletion=True: for each target, one random agent within radius is
    selected; an agent can only be assigned to one target (first-come wins).
    If shared_depletion=False: each agent is assigned to its nearest target within
    radius independently (deterministic).

    Returns agent_to_target[i] = target index for agent i, or -1 if none.
    '''
    na = len(positions)
    nt = len(target_positions)
    r2 = r * r

    agent_to_target = -1 * np.ones(na, dtype=np.int64)

    if shared_depletion:
        # Fixed-size buffer; no reflected list allocation
        agent_buf = np.empty(na, dtype=np.int64)
        agent_assigned = np.zeros(na, dtype=np.bool_)

        for t in range(nt):
            tx = target_positions[t, 0]
            ty = target_positions[t, 1]
            n_near = 0
            for a in range(na):
                dx = positions[a, 0] - tx
                dy = positions[a, 1] - ty
                if dx * dx + dy * dy <= r2:
                    agent_buf[n_near] = a
                    n_near += 1
            if n_near > 0:
                chosen = agent_buf[np.random.randint(0, n_near)]
                if not agent_assigned[chosen]:
                    agent_to_target[chosen] = t
                    agent_assigned[chosen] = True

    else:
        for a in range(na):
            best_t = -1
            best_d2 = r2 + 1.0
            for t in range(nt):
                dx = positions[a, 0] - target_positions[t, 0]
                dy = positions[a, 1] - target_positions[t, 1]
                d2 = dx * dx + dy * dy
                if d2 <= r2 and (best_t == -1 or d2 < best_d2):
                    best_d2 = d2
                    best_t = t
            agent_to_target[a] = best_t

    return agent_to_target


